function fail(
  itemIndex,
  message
) {
  throw new Error(
    `[Подготовить запрос для AI] Item ${
      itemIndex + 1
    }: ${message}`
  );
}


function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}


function uniqueStrings(values) {
  return [
    ...new Set(
      values.filter(
        value =>
          typeof value === 'string' &&
          value.length > 0
      )
    ),
  ];
}


function arraysEqual(
  left,
  right
) {
  if (
    left.length !==
    right.length
  ) {
    return false;
  }

  for (
    let index = 0;
    index < left.length;
    index++
  ) {
    if (
      left[index] !==
      right[index]
    ) {
      return false;
    }
  }

  return true;
}


function sameStringSet(
  left,
  right
) {
  if (
    left.length !==
    right.length
  ) {
    return false;
  }

  const rightSet =
    new Set(right);

  return left.every(
    value =>
      rightSet.has(value)
  );
}


function renderFieldCatalog() {
  return FIELD_CATALOG
    .map(
      (
        field,
        index
      ) =>
        `${
          index + 1
        }. ${field.key} — ${field.title}\n` +
        `   ${field.description}`
    )
    .join('\n\n');
}


function renderAiSegment(segment) {
  return [
    `[SEMANTIC_BLOCK id="${segment.semantic_block_id}" scope="${segment.scope}" type="${segment.type}" role="${segment.role}"]`,
    segment.text,
    '[/SEMANTIC_BLOCK]',
  ].join('\n');
}


