const rows = $input.all().map((item) => {
  const j = item.json;

  return {
    unit_index: j.analysis_batch?.unit_index ?? null,
    analysis_unit_id: j.analysis_unit_meta?.analysis_unit_id ?? null,
    section_title: j.analysis_unit_meta?.section_title ?? null,

    estimated_input_tokens:
      j.ai_request?.stats?.estimated_input_tokens ?? null,

    semantic_blocks_count:
      j.ai_request?.stats?.semantic_blocks_count ?? null,

    primary_blocks_count:
      j.ai_request?.stats?.primary_blocks_count ?? null,

    overlap_blocks_count:
      j.ai_request?.stats?.overlap_blocks_count ?? null,

    contains_table:
      j.analysis_unit_meta?.flags?.contains_table ?? false,

    oversized_atomic_block:
      j.analysis_unit_meta?.flags?.oversized_atomic_block ?? false,
  };
});

const tokenValues = rows
  .map((r) => r.estimated_input_tokens)
  .filter((v) => Number.isFinite(v))
  .sort((a, b) => a - b);

const percentile = (arr, p) => {
  if (!arr.length) return null;
  const idx = Math.ceil((p / 100) * arr.length) - 1;
  return arr[Math.max(0, Math.min(idx, arr.length - 1))];
};

const sum = tokenValues.reduce((a, b) => a + b, 0);

return [
  {
    json: {
      summary: {
        units_total: rows.length,
        tokens_min: tokenValues[0] ?? null,
        tokens_max: tokenValues.at(-1) ?? null,
        tokens_avg: tokenValues.length
          ? Math.round(sum / tokenValues.length)
          : null,
        tokens_p95: percentile(tokenValues, 95),

        units_over_6000: rows.filter(
          (r) => (r.estimated_input_tokens ?? 0) > 6000
        ).length,

        units_over_10000: rows.filter(
          (r) => (r.estimated_input_tokens ?? 0) > 10000
        ).length,

        oversized_atomic_blocks: rows.filter(
          (r) => r.oversized_atomic_block
        ).length,
      },

      problematic_units: rows
        .filter(
          (r) =>
            r.oversized_atomic_block ||
            (r.estimated_input_tokens ?? 0) > 6000
        )
        .sort(
          (a, b) =>
            (b.estimated_input_tokens ?? 0) -
            (a.estimated_input_tokens ?? 0)
        ),

      all_units: rows,
    },
  },
];

const CONFIG = {
  validatorVersion: 'evidence_validator_v2',
  expectedSchemaVersion: 'ai_extractor_v1',
  expectedFieldCatalogVersion: 'tender_fields_v1',
  maxFactsPerUnit: 100,
  maxEvidencePerFact: 25,
  maxQuoteLength: 1500,
  maxTotalQuoteCharsPerFact: 5000,
  maxValueTextLength: 3000,
  maxReviewNoteLength: 500,
};

const FIELD_KEYS = new Set([
  'procurement_subject', 'nm_price_with_vat', 'platform', 'procedure_type',
  'application_deadline', 'application_review_date', 'results_date', 'customer',
  'customer_contacts', 'participation_cost', 'participation_guarantee',
  'evaluation_criteria', 'delivery_term', 'payment_terms',
  'special_account_or_treasury', 'bank_support', 'government_contract',
  'rebidding', 'national_regime', 'advance_contract_guarantee',
  'warranty_obligations_guarantee', 'licenses_certificates',
  'required_official_certificates', 'similar_supply_experience',
  'analog_allowed', 'analog_definition', 'application_documents',
]);
const REVIEW_REASON_CODES = new Set([
  'ambiguous_wording', 'conflicting_evidence', 'incomplete_value',
  'unclear_reference', 'source_quality_issue', 'other',
]);
const ROOT_KEYS = new Set([
  'schema_version', 'field_catalog_version', 'analysis_unit_id', 'facts',
]);
const FACT_KEYS = new Set([
  'field_key', 'value_text', 'status', 'confidence', 'evidence',
  'review_reason_code', 'review_note',
]);
const EVIDENCE_KEYS = new Set(['semantic_block_id', 'quote']);

function hard(message) {
  throw new Error('[Evidence validator] ' + message);
}
function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
const TABLE_COORDINATE_TOKEN_AT_LINE_START = /^[\t ]*\[(?:C[1-9]\d*(?:-C[1-9]\d*)?|R[1-9]\d*(?:-R[1-9]\d*)?,C[1-9]\d*(?:-C[1-9]\d*)?)\][\t ]*/gm;
function normalizeEvidenceWhitespace(value, segmentType = null) {
  const source = String(value ?? '');
  const canonical = segmentType === 'table'
    ? source.replace(TABLE_COORDINATE_TOKEN_AT_LINE_START, '')
    : source;
  return canonical.replace(/\s+/g, ' ').trim();
}
function isExactGroundedEvidence(segment, quote) {
  if (!segment) return false;
  const normalizedQuote = normalizeEvidenceWhitespace(quote, segment.type);
  if (normalizedQuote.length === 0) return false;
  const normalizedSegment = normalizeEvidenceWhitespace(segment.text, segment.type);
  return normalizedSegment.includes(normalizedQuote);
}
function assertExactKeys(value, allowed, path) {
  if (!isObject(value)) hard(path + ': ожидался object.');
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) hard(path + ': недопустимое поле ' + key + '.');
  }
}
function assertString(value, path, minLength = 1, maxLength = Infinity) {
  if (typeof value !== 'string') hard(path + ': ожидалась string.');
  if (value.length < minLength || value.length > maxLength) {
    hard(path + ': недопустимая длина ' + value.length + '.');
  }
}
function parseProviderResponse(apiResponse, expectedRootSchema) {
  if (!isObject(apiResponse)) hard('Некорректный HTTP response.');
  if (!Array.isArray(apiResponse.choices) || apiResponse.choices.length === 0) {
    hard('Provider не вернул choices.');
  }
  const choice = apiResponse.choices[0];
  if (!isObject(choice) || choice.finish_reason !== 'stop' || !isObject(choice.message)) {
    hard('Provider response не завершён корректно.');
  }
  assertString(choice.message.content, 'choices[0].message.content');
  let parsed;
  try {
    parsed = JSON.parse(choice.message.content.trim());
  } catch (error) {
    hard('Ответ не является валидным JSON: ' + error.message);
  }
  if (!isObject(parsed)) hard('Корневой JSON должен быть object.');
  if (expectedRootSchema === 'extractor') assertExactKeys(parsed, ROOT_KEYS, 'AIExtractorV1');
  return { choice, parsed };
}
function buildSourceIndexes(source) {
  const unitId = source?.analysis_unit_meta?.analysis_unit_id;
  assertString(unitId, 'analysis_unit_meta.analysis_unit_id');
  if (!Array.isArray(source.ai_segments) || source.ai_segments.length === 0) {
    hard(unitId + ': ai_segments отсутствует.');
  }
  if (!isObject(source.provenance?.index)) hard(unitId + ': provenance.index отсутствует.');
  const segmentMap = new Map();
  for (const segment of source.ai_segments) {
    if (!isObject(segment)) hard(unitId + ': invalid ai_segment.');
    assertString(segment.semantic_block_id, unitId + '.semantic_block_id');
    assertString(segment.text, unitId + '.' + segment.semantic_block_id + '.text');
    if (segment.scope !== 'primary' && segment.scope !== 'overlap') {
      hard(unitId + ': invalid scope for ' + segment.semantic_block_id + '.');
    }
    if (segmentMap.has(segment.semantic_block_id)) {
      hard(unitId + ': duplicate semantic_block_id ' + segment.semantic_block_id + '.');
    }
    segmentMap.set(segment.semantic_block_id, segment);
  }
  return { unitId, segmentMap, provenanceIndex: source.provenance.index };
}
function addViolation(violations, code, factIndex, evidenceIndex, details = {}) {
  violations.push({ code, fact_index: factIndex, evidence_index: evidenceIndex, details });
}
function validateFacts(facts, source, validationAttempt = 1) {
  if (!Array.isArray(facts)) hard('facts должен быть array.');
  if (facts.length > CONFIG.maxFactsPerUnit) hard('facts превышает ' + CONFIG.maxFactsPerUnit + '.');
  const { unitId, segmentMap, provenanceIndex } = buildSourceIndexes(source);
  const violations = [];
  const verifiedFacts = [];
  const deterministicallyRejectedFacts = [];
  const resolvedViolations = [];
  const evidenceContext = {};
  const metrics = {
    facts_count: facts.length,
    evidence_count: 0,
    max_evidence_count_per_fact: 0,
    total_quote_chars: 0,
    max_total_quote_chars_per_fact: 0,
    duplicate_evidence_count: 0,
  };

  facts.forEach((fact, factIndex) => {
    const factPath = 'facts[' + factIndex + ']';
    assertExactKeys(fact, FACT_KEYS, factPath);
    for (const required of FACT_KEYS) {
      if (!Object.prototype.hasOwnProperty.call(fact, required)) hard(factPath + ': отсутствует ' + required + '.');
    }
    assertString(fact.field_key, factPath + '.field_key');
    if (!FIELD_KEYS.has(fact.field_key)) hard(factPath + ': недопустимый field_key ' + fact.field_key + '.');
    assertString(fact.value_text, factPath + '.value_text', 1, CONFIG.maxValueTextLength);
    if (fact.status !== 'found' && fact.status !== 'requires_review') hard(factPath + ': invalid status.');
    if (typeof fact.confidence !== 'number' || !Number.isFinite(fact.confidence) || fact.confidence < 0 || fact.confidence > 1) {
      hard(factPath + ': invalid confidence.');
    }
    if (fact.status === 'found' && (fact.review_reason_code !== null || fact.review_note !== null)) {
      hard(factPath + ': review fields должны быть null для found.');
    }
    if (fact.status === 'requires_review') {
      if (!REVIEW_REASON_CODES.has(fact.review_reason_code)) hard(factPath + ': invalid review_reason_code.');
      if (fact.review_note !== null) assertString(fact.review_note, factPath + '.review_note', 0, CONFIG.maxReviewNoteLength);
    }
    if (!Array.isArray(fact.evidence) || fact.evidence.length === 0) {
      hard(factPath + ': evidence отсутствует или пуст.');
    }

    const factViolations = [];
    const totalQuoteChars = fact.evidence.reduce((sum, evidence) => sum + (typeof evidence?.quote === 'string' ? evidence.quote.length : 0), 0);
    metrics.evidence_count += fact.evidence.length;
    metrics.total_quote_chars += totalQuoteChars;
    metrics.max_evidence_count_per_fact = Math.max(metrics.max_evidence_count_per_fact, fact.evidence.length);
    metrics.max_total_quote_chars_per_fact = Math.max(metrics.max_total_quote_chars_per_fact, totalQuoteChars);
    if (fact.evidence.length > CONFIG.maxEvidencePerFact) {
      addViolation(factViolations, 'evidence_limit_exceeded', factIndex, null, {
        actual: fact.evidence.length, maximum: CONFIG.maxEvidencePerFact,
      });
    }
    if (totalQuoteChars > CONFIG.maxTotalQuoteCharsPerFact) {
      addViolation(factViolations, 'evidence_total_quote_chars_exceeded', factIndex, null, {
        actual: totalQuoteChars, maximum: CONFIG.maxTotalQuoteCharsPerFact,
      });
    }

    const seen = new Set();
    const groundedEvidence = [];
    fact.evidence.forEach((evidence, evidenceIndex) => {
      const evidencePath = factPath + '.evidence[' + evidenceIndex + ']';
      assertExactKeys(evidence, EVIDENCE_KEYS, evidencePath);
      for (const required of EVIDENCE_KEYS) {
        if (!Object.prototype.hasOwnProperty.call(evidence, required)) hard(evidencePath + ': отсутствует ' + required + '.');
      }
      assertString(evidence.semantic_block_id, evidencePath + '.semantic_block_id', 1, 120);
      if (!/^sb_[A-Za-z0-9_-]+$/.test(evidence.semantic_block_id)) hard(evidencePath + ': invalid semantic_block_id shape.');
      assertString(evidence.quote, evidencePath + '.quote', 1, CONFIG.maxQuoteLength);
      const pairKey = evidence.semantic_block_id + '\u0000' + evidence.quote;
      if (seen.has(pairKey)) {
        metrics.duplicate_evidence_count += 1;
        addViolation(factViolations, 'duplicate_evidence', factIndex, evidenceIndex, {
          semantic_block_id: evidence.semantic_block_id,
        });
        return;
      }
      seen.add(pairKey);

      const segment = segmentMap.get(evidence.semantic_block_id);
      if (!segment) {
        const candidateIds = [...segmentMap.values()]
          .filter((candidate) => isExactGroundedEvidence(candidate, evidence.quote))
          .map((candidate) => candidate.semantic_block_id);
        addViolation(factViolations, 'unknown_semantic_block_id', factIndex, evidenceIndex, {
          semantic_block_id: evidence.semantic_block_id,
          exact_match_candidate_ids: candidateIds,
        });
        return;
      }
      const provenance = provenanceIndex[evidence.semantic_block_id];
      if (!isObject(provenance)) hard(evidencePath + ': provenance отсутствует.');
      if (provenance.scope !== segment.scope) hard(evidencePath + ': scope mismatch in provenance.');
      if (!isExactGroundedEvidence(segment, evidence.quote)) {
        const candidateIds = [...segmentMap.values()]
          .filter((candidate) => candidate.semantic_block_id !== evidence.semantic_block_id)
          .filter((candidate) => isExactGroundedEvidence(candidate, evidence.quote))
          .map((candidate) => candidate.semantic_block_id);
        addViolation(
          factViolations,
          candidateIds.length > 0 ? 'wrong_semantic_block_id' : 'quote_not_found',
          factIndex,
          evidenceIndex,
          {
            semantic_block_id: evidence.semantic_block_id,
            exact_match_candidate_ids: candidateIds,
          },
        );
        return;
      }
      groundedEvidence.push({
        semantic_block_id: evidence.semantic_block_id,
        quote: evidence.quote,
        scope: segment.scope,
        type: segment.type ?? null,
        role: segment.role ?? null,
        source_block_ids: Array.isArray(provenance.source_block_ids) ? provenance.source_block_ids : [],
        page_from: provenance.page_from ?? null,
        page_to: provenance.page_to ?? null,
        sheet_name: provenance.sheet_name ?? null,
        sources: Array.isArray(provenance.sources) ? provenance.sources : [],
      });
    });

    if (!groundedEvidence.some((evidence) => evidence.scope === 'primary')) {
      const allGroundedOverlap = groundedEvidence.length === fact.evidence.length && groundedEvidence.every((evidence) => evidence.scope === 'overlap');
      addViolation(
        factViolations,
        allGroundedOverlap ? 'overlap_only' : 'missing_primary_evidence',
        factIndex,
        null,
        { grounded_evidence_count: groundedEvidence.length },
      );
    }
    const registerGroundedEvidenceContext = () => {
      for (const evidence of groundedEvidence) {
        const segment = segmentMap.get(evidence.semantic_block_id);
        const provenance = provenanceIndex[evidence.semantic_block_id];
        evidenceContext[evidence.semantic_block_id] = {
          semantic_block_id: evidence.semantic_block_id,
          scope: segment.scope,
          type: segment.type ?? null,
          role: segment.role ?? null,
          text: segment.text,
          provenance,
        };
      }
    };
    const pureOverlapOnly = (
      factViolations.length === 1 &&
      factViolations[0].code === 'overlap_only'
    );
    if (pureOverlapOnly) {
      registerGroundedEvidenceContext();
      const originalViolationCodes = factViolations.map(({ code }) => code);
      deterministicallyRejectedFacts.push({
        fact_index: factIndex,
        field_key: fact.field_key,
        value_text: fact.value_text,
        status: fact.status,
        confidence: fact.confidence,
        evidence: groundedEvidence,
        review_reason_code: fact.review_reason_code,
        review_note: fact.review_note,
        validator_verdict: 'rejected',
        validator_confidence: 1.0,
        validator_reason_code: 'overlap_only_context_only',
        accepted_for_normalization: false,
        original_violations: factViolations.map((violation) => ({ ...violation })),
        deterministic_rejection: {
          version: 'deterministic_overlap_rejection_v1',
          validation_attempt: validationAttempt,
          reason_code: 'overlap_only_context_only',
          grounding: 'exact',
          evidence_scope: 'overlap_only',
        },
        validator_meta: {
          origin: 'deterministic_evidence_layer',
          ai_validator_called_for_fact: false,
          grounding: 'exact',
          evidence_scope: 'overlap_only',
          analysis_unit_id: unitId,
          fact_index: factIndex,
          version: 'deterministic_overlap_rejection_v1',
          validation_attempt: validationAttempt,
          original_violation_codes: originalViolationCodes,
        },
      });
      resolvedViolations.push(...factViolations);
    } else {
      violations.push(...factViolations);
      if (factViolations.length === 0) {
        registerGroundedEvidenceContext();
        verifiedFacts.push({
          fact_index: factIndex,
          field_key: fact.field_key,
          value_text: fact.value_text,
          status: fact.status,
          confidence: fact.confidence,
          evidence: groundedEvidence,
          review_reason_code: fact.review_reason_code,
          review_note: fact.review_note,
        });
      }
    }
  });

  violations.sort((left, right) =>
    (left.fact_index - right.fact_index) ||
    ((left.evidence_index ?? -1) - (right.evidence_index ?? -1)) ||
    left.code.localeCompare(right.code),
  );
  const violationsByCode = {};
  for (const violation of [...violations, ...resolvedViolations]) {
    violationsByCode[violation.code] = (violationsByCode[violation.code] ?? 0) + 1;
  }
  metrics.violations_by_code = violationsByCode;
  metrics.unresolved_violations_count = violations.length;
  metrics.resolved_violations_count = resolvedViolations.length;
  metrics.deterministically_rejected_facts_count = deterministicallyRejectedFacts.length;
  return {
    unitId,
    violations,
    verifiedFacts,
    deterministicallyRejectedFacts,
    resolvedViolations,
    evidenceContext,
    metrics,
  };
}

const apiResponse = $json;
const source = $('Подготовить запрос для AI').item.json;
if (!isObject(source)) hard('Не удалось восстановить source analysis unit.');
const { choice, parsed } = parseProviderResponse(apiResponse, 'extractor');
if (parsed.schema_version !== CONFIG.expectedSchemaVersion) hard('Неверный schema_version.');
if (parsed.field_catalog_version !== CONFIG.expectedFieldCatalogVersion) hard('Неверный field_catalog_version.');
const expectedUnitId = source.analysis_unit_meta?.analysis_unit_id;
if (parsed.analysis_unit_id !== expectedUnitId) hard('analysis_unit_id не совпадает.');
const validation = validateFacts(parsed.facts, source, 1);
const usage = isObject(apiResponse.usage) ? apiResponse.usage : {};
const extractor = {
  provider: 'deepseek',
  response_id: apiResponse.id ?? null,
  model: apiResponse.model ?? null,
  finish_reason: choice.finish_reason,
  system_fingerprint: apiResponse.system_fingerprint ?? null,
  prompt_version: source.ai_request?.prompt_version ?? null,
  schema_version: parsed.schema_version,
  field_catalog_version: parsed.field_catalog_version,
  repair: { attempted: false, requests_count: 0 },
  evidence_diagnostics: {
    validator_version: CONFIG.validatorVersion,
    attempt: 1,
    validation_passed: validation.violations.length === 0,
    resource_contract: {
      max_evidence_per_fact: CONFIG.maxEvidencePerFact,
      max_quote_length: CONFIG.maxQuoteLength,
      max_total_quote_chars_per_fact: CONFIG.maxTotalQuoteCharsPerFact,
    },
    resource_metrics: validation.metrics,
    violations: validation.violations,
    resolved_violations: validation.resolvedViolations,
    deterministically_rejected_facts_count: validation.deterministicallyRejectedFacts.length,
  },
  usage,
};
const passed = validation.violations.length === 0;
return {
  json: {
    tender: source.tender ?? null,
    document: source.document ?? null,
    analysis_batch: source.analysis_batch ?? null,
    analysis_unit_meta: source.analysis_unit_meta ?? null,
    validation_attempt: 1,
    validation_passed: passed,
    violations: validation.violations,
    verified_facts: validation.verifiedFacts,
    deterministically_rejected_facts: validation.deterministicallyRejectedFacts,
    resolved_violations: validation.resolvedViolations,
    evidence_context: validation.evidenceContext,
    extractor,
    evidence_validation: {
      version: CONFIG.validatorVersion,
      attempt: 1,
      passed,
      facts_count: validation.verifiedFacts.length,
      deterministically_rejected_facts_count: validation.deterministicallyRejectedFacts.length,
      evidence_count: [...validation.verifiedFacts, ...validation.deterministicallyRejectedFacts].reduce((sum, fact) => sum + fact.evidence.length, 0),
      resource_contract: {
        max_evidence_per_fact: CONFIG.maxEvidencePerFact,
        max_quote_length: CONFIG.maxQuoteLength,
        max_total_quote_chars_per_fact: CONFIG.maxTotalQuoteCharsPerFact,
      },
      resource_metrics: validation.metrics,
      violations_count: validation.violations.length,
    },
    repair_context: passed ? null : {
      original_extractor_response: parsed,
      original_api_response_meta: extractor,
      ai_segments: source.ai_segments,
      provenance: source.provenance,
      field_catalog: source.ai_request?.field_catalog ?? [],
      source,
    },
  },
};

const CONFIG = {
  validatorVersion: 'evidence_validator_v1',

  expectedSchemaVersion: 'ai_extractor_v1',
  expectedFieldCatalogVersion: 'tender_fields_v1',

  sourceNodeName: 'Подготовить запрос для AI',

  // Только для временной TEST-копии ноды
  testAnalysisUnitId: 'doc_7_au_0022',

  maxFactsPerUnit: 100,
  maxEvidencePerFact: 5,
  maxValueTextLength: 3000,
  maxQuoteLength: 1500,
  maxReviewNoteLength: 500,
};


// ============================================================
// 1. РАЗРЕШЁННЫЕ ПОЛЯ tender_fields_v1
// ============================================================

const FIELD_KEYS = new Set([
  'procurement_subject',
  'nm_price_with_vat',
  'platform',
  'procedure_type',
  'application_deadline',
  'application_review_date',
  'results_date',
  'customer',
  'customer_contacts',
  'participation_cost',
  'participation_guarantee',
  'evaluation_criteria',
  'delivery_term',
  'payment_terms',
  'special_account_or_treasury',
  'bank_support',
  'government_contract',
  'rebidding',
  'national_regime',
  'advance_contract_guarantee',
  'warranty_obligations_guarantee',
  'licenses_certificates',
  'required_official_certificates',
  'similar_supply_experience',
  'analog_allowed',
  'analog_definition',
  'application_documents',
]);


const REVIEW_REASON_CODES = new Set([
  'ambiguous_wording',
  'conflicting_evidence',
  'incomplete_value',
  'unclear_reference',
  'source_quality_issue',
  'other',
]);


const FACT_ALLOWED_KEYS = new Set([
  'field_key',
  'value_text',
  'status',
  'confidence',
  'evidence',
  'review_reason_code',
  'review_note',
]);


const EVIDENCE_ALLOWED_KEYS = new Set([
  'semantic_block_id',
  'quote',
]);


const ROOT_ALLOWED_KEYS = new Set([
  'schema_version',
  'field_catalog_version',
  'analysis_unit_id',
  'facts',
]);


// ============================================================
// 2. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ============================================================

function fail(itemIndex, message) {
  throw new Error(
    `[Проверить и привязать evidence] Item ${
      itemIndex + 1
    }: ${message}`
  );
}


function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function normalizeEvidenceWhitespace(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function assertNoExtraKeys(
  object,
  allowedKeys,
  itemIndex,
  path
) {
  for (const key of Object.keys(object)) {
    if (!allowedKeys.has(key)) {
      fail(
        itemIndex,
        `${path}: обнаружено недопустимое поле "${key}".`
      );
    }
  }
}


function assertString(
  value,
  itemIndex,
  path,
  {
    minLength = 1,
    maxLength = Infinity,
  } = {}
) {
  if (typeof value !== 'string') {
    fail(
      itemIndex,
      `${path}: ожидалась строка.`
    );
  }

  if (value.length < minLength) {
    fail(
      itemIndex,
      `${path}: строка слишком короткая.`
    );
  }

  if (value.length > maxLength) {
    fail(
      itemIndex,
      `${path}: превышена максимальная длина ${maxLength}.`
    );
  }
}


function parseExtractorContent(
  content,
  itemIndex
) {
  if (
    typeof content !== 'string' ||
    content.trim().length === 0
  ) {
    fail(
      itemIndex,
      'choices[0].message.content пуст.'
    );
  }

  try {
    return JSON.parse(
      content.trim()
    );
  } catch (error) {
    fail(
      itemIndex,
      `Ответ AI не является валидным JSON: ${error.message}`
    );
  }
}


function createSegmentMap(
  aiSegments,
  itemIndex,
  analysisUnitId
) {
  if (!Array.isArray(aiSegments)) {
    fail(
      itemIndex,
      `${analysisUnitId}: ai_segments отсутствует.`
    );
  }

  const map = new Map();

  for (const segment of aiSegments) {
    if (!isObject(segment)) {
      fail(
        itemIndex,
        `${analysisUnitId}: некорректный элемент ai_segments.`
      );
    }

    const id =
      segment.semantic_block_id;

    assertString(
      id,
      itemIndex,
      `${analysisUnitId}.ai_segments.semantic_block_id`
    );

    if (map.has(id)) {
      fail(
        itemIndex,
        `${analysisUnitId}: duplicate semantic_block_id ${id}.`
      );
    }

    if (
      segment.scope !== 'primary' &&
      segment.scope !== 'overlap'
    ) {
      fail(
        itemIndex,
        `${analysisUnitId}: ${id} имеет недопустимый scope "${segment.scope}".`
      );
    }

    assertString(
      segment.text,
      itemIndex,
      `${analysisUnitId}.${id}.text`
    );

    map.set(
      id,
      segment
    );
  }

  return map;
}


// ============================================================
// 3. INPUT
// ============================================================

const extractorItems = $input.all();

const sourceItems =
  $(CONFIG.sourceNodeName).all();

if (extractorItems.length === 0) {
  throw new Error(
    '[Проверить и привязать evidence TEST] Нет входных items.'
  );
}

// В TEST-режиме ожидаем ровно один ответ Extractor.
if (extractorItems.length !== 1) {
  throw new Error(
    `[Проверить и привязать evidence TEST] ` +
    `Ожидался 1 item от AI Extractor, получено ${extractorItems.length}.`
  );
}

// Ищем исходный source не по позиции item,
// а по конкретному analysis_unit_id.
const testSourceItem = sourceItems.find(
  item =>
    item?.json?.analysis_unit_meta
      ?.analysis_unit_id ===
    CONFIG.testAnalysisUnitId
);

if (!testSourceItem) {
  throw new Error(
    `[Проверить и привязать evidence TEST] ` +
    `Не найден source для analysis_unit_id="${CONFIG.testAnalysisUnitId}".`
  );
}

const testSource =
  testSourceItem.json;


// ============================================================
// 4. ОБРАБОТКА
// ============================================================

return extractorItems.map(
  (
    extractorItem,
    itemIndex
  ) => {
    const apiResponse =
      extractorItem?.json;


const source = testSource;

    if (!isObject(apiResponse)) {
      fail(
        itemIndex,
        'Некорректный ответ HTTP Request.'
      );
    }


    if (!isObject(source)) {
      fail(
        itemIndex,
        `Не удалось получить исходные данные из ноды "${CONFIG.sourceNodeName}".`
      );
    }


    // --------------------------------------------------------
    // Проверяем ответ DeepSeek
    // --------------------------------------------------------

    if (
      !Array.isArray(apiResponse.choices) ||
      apiResponse.choices.length === 0
    ) {
      fail(
        itemIndex,
        'DeepSeek не вернул choices.'
      );
    }


    const choice =
      apiResponse.choices[0];

    if (!isObject(choice)) {
      fail(
        itemIndex,
        'choices[0] имеет неверный формат.'
      );
    }


    if (
      choice.finish_reason !== 'stop'
    ) {
      fail(
        itemIndex,
        `AI завершил ответ с finish_reason="${choice.finish_reason}".`
      );
    }


    if (!isObject(choice.message)) {
      fail(
        itemIndex,
        'choices[0].message отсутствует.'
      );
    }


    const parsed =
      parseExtractorContent(
        choice.message.content,
        itemIndex
      );


    if (!isObject(parsed)) {
      fail(
        itemIndex,
        'Корневой JSON AI Extractor должен быть объектом.'
      );
    }


    // --------------------------------------------------------
    // Проверяем root schema
    // --------------------------------------------------------

    assertNoExtraKeys(
      parsed,
      ROOT_ALLOWED_KEYS,
      itemIndex,
      'AIExtractorV1'
    );


    if (
      parsed.schema_version !==
      CONFIG.expectedSchemaVersion
    ) {
      fail(
        itemIndex,
        `Неверный schema_version: "${parsed.schema_version}".`
      );
    }


    if (
      parsed.field_catalog_version !==
      CONFIG.expectedFieldCatalogVersion
    ) {
      fail(
        itemIndex,
        `Неверный field_catalog_version: "${parsed.field_catalog_version}".`
      );
    }


    const expectedAnalysisUnitId =
      source.analysis_unit_meta
        ?.analysis_unit_id;


    assertString(
      expectedAnalysisUnitId,
      itemIndex,
      'analysis_unit_meta.analysis_unit_id'
    );


    if (
      parsed.analysis_unit_id !==
      expectedAnalysisUnitId
    ) {
      fail(
        itemIndex,
        `analysis_unit_id не совпадает. ` +
        `Ожидался "${expectedAnalysisUnitId}", ` +
        `получен "${parsed.analysis_unit_id}".`
      );
    }


    if (!Array.isArray(parsed.facts)) {
      fail(
        itemIndex,
        `${expectedAnalysisUnitId}: facts должен быть массивом.`
      );
    }


    if (
      parsed.facts.length >
      CONFIG.maxFactsPerUnit
    ) {
      fail(
        itemIndex,
        `${expectedAnalysisUnitId}: facts превышает ${CONFIG.maxFactsPerUnit}.`
      );
    }


    // --------------------------------------------------------
    // Исходные semantic blocks + provenance
    // --------------------------------------------------------

    const segmentMap =
      createSegmentMap(
        source.ai_segments,
        itemIndex,
        expectedAnalysisUnitId
      );


    const provenanceIndex =
      source.provenance?.index;


    if (!isObject(provenanceIndex)) {
      fail(
        itemIndex,
        `${expectedAnalysisUnitId}: provenance.index отсутствует.`
      );
    }


    const verifiedFacts = [];

    // Храним полный текст использованных semantic blocks
    // только один раз, чтобы не дублировать большие таблицы
    // внутри каждого fact.
    const evidenceContext = {};


    // --------------------------------------------------------
    // Проверяем каждый fact
    // --------------------------------------------------------

    parsed.facts.forEach(
      (
        fact,
        factIndex
      ) => {
        const factPath =
          `facts[${factIndex}]`;


        if (!isObject(fact)) {
          fail(
            itemIndex,
            `${factPath}: fact должен быть объектом.`
          );
        }


        assertNoExtraKeys(
          fact,
          FACT_ALLOWED_KEYS,
          itemIndex,
          factPath
        );


        // field_key
        assertString(
          fact.field_key,
          itemIndex,
          `${factPath}.field_key`
        );


        if (
          !FIELD_KEYS.has(
            fact.field_key
          )
        ) {
          fail(
            itemIndex,
            `${factPath}: недопустимый field_key "${fact.field_key}".`
          );
        }


        // value_text
        assertString(
          fact.value_text,
          itemIndex,
          `${factPath}.value_text`,
          {
            minLength: 1,
            maxLength:
              CONFIG.maxValueTextLength,
          }
        );


        // status
        if (
          fact.status !== 'found' &&
          fact.status !== 'requires_review'
        ) {
          fail(
            itemIndex,
            `${factPath}: недопустимый status "${fact.status}".`
          );
        }


        // confidence
        if (
          typeof fact.confidence !== 'number' ||
          !Number.isFinite(
            fact.confidence
          ) ||
          fact.confidence < 0 ||
          fact.confidence > 1
        ) {
          fail(
            itemIndex,
            `${factPath}: confidence должен быть числом от 0 до 1.`
          );
        }


        // ----------------------------------------------------
// Нормализация review-полей
//
// LLM может не вернуть ключ вообще.
// Внутри системы всегда используем единый контракт.
// ----------------------------------------------------

if (
  !Object.prototype.hasOwnProperty.call(
    fact,
    'review_reason_code'
  )
) {
  fact.review_reason_code = null;
}


if (
  !Object.prototype.hasOwnProperty.call(
    fact,
    'review_note'
  )
) {
  fact.review_note = null;
}



          // review fields
if (
  fact.status === 'found'
) {
  if (
    fact.review_reason_code !== null
  ) {
    fail(
      itemIndex,
      `${factPath}: для status=found review_reason_code должен быть пустым.`
    );
  }

  if (
    fact.review_note !== null
  ) {
    fail(
      itemIndex,
      `${factPath}: для status=found review_note должен быть пустым.`
    );
  }
}


        if (
          fact.status ===
          'requires_review'
        ) {
          if (
            !REVIEW_REASON_CODES.has(
              fact.review_reason_code
            )
          ) {
            fail(
              itemIndex,
              `${factPath}: неверный review_reason_code "${fact.review_reason_code}".`
            );
          }

          if (
            fact.review_note !== null
          ) {
            assertString(
              fact.review_note,
              itemIndex,
              `${factPath}.review_note`,
              {
                minLength: 0,
                maxLength:
                  CONFIG.maxReviewNoteLength,
              }
            );
          }
        }


        // ----------------------------------------------------
        // Evidence
        // ----------------------------------------------------

        if (
          !Array.isArray(
            fact.evidence
          ) ||
          fact.evidence.length === 0
        ) {
          fail(
            itemIndex,
            `${factPath}: evidence отсутствует или пуст.`
          );
        }


        if (
          fact.evidence.length >
          CONFIG.maxEvidencePerFact
        ) {
          fail(
            itemIndex,
            `${factPath}: evidence превышает ${CONFIG.maxEvidencePerFact}.`
          );
        }


        const usedEvidenceKeys =
          new Set();

        const verifiedEvidence = [];


        fact.evidence.forEach(
          (
            evidence,
            evidenceIndex
          ) => {
            const evidencePath =
              `${factPath}.evidence[${evidenceIndex}]`;


            if (!isObject(evidence)) {
              fail(
                itemIndex,
                `${evidencePath}: evidence должен быть объектом.`
              );
            }


            assertNoExtraKeys(
              evidence,
              EVIDENCE_ALLOWED_KEYS,
              itemIndex,
              evidencePath
            );


            const semanticBlockId =
              evidence.semantic_block_id;


            assertString(
              semanticBlockId,
              itemIndex,
              `${evidencePath}.semantic_block_id`
            );


            if (
              !/^sb_[A-Za-z0-9_-]+$/.test(
                semanticBlockId
              )
            ) {
              fail(
                itemIndex,
                `${evidencePath}: неверный semantic_block_id "${semanticBlockId}".`
              );
            }




            assertString(
              evidence.quote,
              itemIndex,
              `${evidencePath}.quote`,
              {
                minLength: 1,
                maxLength:
                  CONFIG.maxQuoteLength,
              }
            );

            const evidenceKey =
  `${semanticBlockId}\u0000${evidence.quote}`;

if (
  usedEvidenceKeys.has(
    evidenceKey
  )
) {
  return;
}

usedEvidenceKeys.add(
  evidenceKey
);

            const segment =
              segmentMap.get(
                semanticBlockId
              );


            if (!segment) {
              fail(
                itemIndex,
                `${evidencePath}: semantic block "${semanticBlockId}" отсутствует в текущей analysis unit.`
              );
            }


            const provenance =
              provenanceIndex[
                semanticBlockId
              ];


            if (!isObject(provenance)) {
              fail(
                itemIndex,
                `${evidencePath}: provenance для "${semanticBlockId}" отсутствует.`
              );
            }


            if (
              provenance.scope !==
              segment.scope
            ) {
              fail(
                itemIndex,
                `${evidencePath}: scope не совпадает между ai_segments и provenance.`
              );
            }


            // ------------------------------------------------
           // ------------------------------------------------
  // Главная grounded-проверка:
  // содержание quote обязано существовать
  // внутри указанного semantic block.
  //
  // Разрешаем только технические различия whitespace:
  // перенос строки / tab / несколько пробелов.
  // Слова, цифры и пунктуация по-прежнему
  // должны совпадать.
  // ------------------------------------------------

  const normalizedSegmentText =
    normalizeEvidenceWhitespace(
      segment.text
    );

  const normalizedQuote =
    normalizeEvidenceWhitespace(
      evidence.quote
    );

  if (
    !normalizedSegmentText.includes(
      normalizedQuote
    )
  ) {
    fail(
      itemIndex,
      `${evidencePath}: quote не найден в ${semanticBlockId} после нормализации пробелов.`
    );
}


            verifiedEvidence.push({
              semantic_block_id:
                semanticBlockId,

              quote:
                evidence.quote,

              scope:
                segment.scope,

              type:
                segment.type ??
                null,

              role:
                segment.role ??
                null,

              source_block_ids:
                Array.isArray(
                  provenance.source_block_ids
                )
                  ? provenance.source_block_ids
                  : [],

              page_from:
                provenance.page_from ??
                null,

              page_to:
                provenance.page_to ??
                null,

              sheet_name:
                provenance.sheet_name ??
                null,

              sources:
                Array.isArray(
                  provenance.sources
                )
                  ? provenance.sources
                  : [],
            });


            // Полный текст блока сохраняем один раз.
            if (
              !evidenceContext[
                semanticBlockId
              ]
            ) {
              evidenceContext[
                semanticBlockId
              ] = {
                semantic_block_id:
                  semanticBlockId,

                scope:
                  segment.scope,

                type:
                  segment.type ??
                  null,

                role:
                  segment.role ??
                  null,

                text:
                  segment.text,

                provenance: {
                  section_id:
                    provenance.section_id ??
                    null,

                  section_title:
                    provenance.section_title ??
                    null,

                  section_path:
                    Array.isArray(
                      provenance.section_path
                    )
                      ? provenance.section_path
                      : [],

                  sheet_name:
                    provenance.sheet_name ??
                    null,

                  page_from:
                    provenance.page_from ??
                    null,

                  page_to:
                    provenance.page_to ??
                    null,

                  source_block_ids:
                    Array.isArray(
                      provenance.source_block_ids
                    )
                      ? provenance.source_block_ids
                      : [],

                  sources:
                    Array.isArray(
                      provenance.sources
                    )
                      ? provenance.sources
                      : [],
                },
              };
            }
          }
        );


        // ----------------------------------------------------
        // Хотя бы одно evidence обязано быть primary
        // ----------------------------------------------------

        const hasPrimaryEvidence =
          verifiedEvidence.some(
            evidence =>
              evidence.scope ===
              'primary'
          );


        if (!hasPrimaryEvidence) {
          fail(
            itemIndex,
            `${factPath}: факт подтверждён только overlap evidence.`
          );
        }


        // ----------------------------------------------------
        // Fact считается технически подтверждённым
        // ----------------------------------------------------

        verifiedFacts.push({
          fact_index:
            factIndex,

          field_key:
            fact.field_key,

          value_text:
            fact.value_text,

          status:
            fact.status,

          confidence:
            fact.confidence,

          evidence:
            verifiedEvidence,

          review_reason_code:
            fact.review_reason_code,

          review_note:
            fact.review_note,
        });
      }
    );


    // ========================================================
    // 5. METRICS
    // ========================================================

    const usage =
      isObject(apiResponse.usage)
        ? apiResponse.usage
        : {};


    const reasoningTokens =
      usage
        ?.completion_tokens_details
        ?.reasoning_tokens ??
      null;


    const totalEvidenceCount =
      verifiedFacts.reduce(
        (
          total,
          fact
        ) =>
          total +
          fact.evidence.length,
        0
      );


    // ========================================================
    // 6. OUTPUT
    // ========================================================

    return {
      json: {
        tender:
          source.tender ??
          null,

        document:
          source.document ??
          null,

        analysis_batch:
          source.analysis_batch ??
          null,

        analysis_unit_meta:
          source.analysis_unit_meta ??
          null,


        // --------------------------------------------
        // Что именно сделал Extractor
        // --------------------------------------------

        extractor: {
          provider:
            'deepseek',

          response_id:
            apiResponse.id ??
            null,

          model:
            apiResponse.model ??
            null,

          finish_reason:
            choice.finish_reason,

          system_fingerprint:
            apiResponse.system_fingerprint ??
            null,

          prompt_version:
            source.ai_request
              ?.prompt_version ??
            null,

          schema_version:
            parsed.schema_version,

          field_catalog_version:
            parsed.field_catalog_version,

          usage: {
            prompt_tokens:
              usage.prompt_tokens ??
              null,

            completion_tokens:
              usage.completion_tokens ??
              null,

            reasoning_tokens:
              reasoningTokens,

            total_tokens:
              usage.total_tokens ??
              null,

            prompt_cache_hit_tokens:
              usage.prompt_cache_hit_tokens ??
              null,

            prompt_cache_miss_tokens:
              usage.prompt_cache_miss_tokens ??
              null,
          },
        },


        // --------------------------------------------
        // Результат детерминированной проверки
        // --------------------------------------------

        evidence_validation: {
          version:
            CONFIG.validatorVersion,

          passed:
            true,

          facts_count:
            verifiedFacts.length,

          evidence_count:
            totalEvidenceCount,

          unique_evidence_blocks_count:
            Object.keys(
              evidenceContext
            ).length,

          schema_valid:
            true,

          analysis_unit_id_valid:
            true,

          field_keys_valid:
            true,

          quotes_valid:
            true,

          primary_evidence_valid:
            true,

          provenance_bound:
            true,
        },


        // --------------------------------------------
        // Теперь это технически проверенные кандидаты
        // --------------------------------------------

        verified_facts:
          verifiedFacts,


        // --------------------------------------------
        // Полные тексты использованных evidence blocks.
        // Нужны следующему AI Validator.
        // Каждый block хранится только один раз.
        // --------------------------------------------

        evidence_context:
          evidenceContext,
      },

      pairedItem: {
        item: itemIndex,
      },
    };
  }
);

const TARGET_ANALYSIS_UNIT_ID = 'doc_7_au_0022';
const START_ROW = 90;
const END_ROW = 90;

const items = $input.all();

const targetItem = items.find(
  item =>
    item?.json?.analysis_unit_meta?.analysis_unit_id ===
    TARGET_ANALYSIS_UNIT_ID
);

if (!targetItem) {
  throw new Error(
    `[TEST oversized table slice] Не найден analysis_unit_id=${TARGET_ANALYSIS_UNIT_ID}`
  );
}

const source = JSON.parse(JSON.stringify(targetItem.json));

if (!Array.isArray(source.ai_segments)) {
  throw new Error(
    '[TEST oversized table slice] ai_segments отсутствует'
  );
}

// ------------------------------------------------------------
// 1. Находим oversized primary table block
// ------------------------------------------------------------

const oversizedTableId =
  source.analysis_unit_meta?.flags?.table_semantic_block_ids?.[0];

if (!oversizedTableId) {
  throw new Error(
    '[TEST oversized table slice] Не найден table_semantic_block_id'
  );
}

const tableSegment = source.ai_segments.find(
  segment =>
    segment.semantic_block_id === oversizedTableId
);

if (!tableSegment) {
  throw new Error(
    `[TEST oversized table slice] Не найден segment ${oversizedTableId}`
  );
}

if (tableSegment.type !== 'table') {
  throw new Error(
    `[TEST oversized table slice] ${oversizedTableId} не является table`
  );
}

// ------------------------------------------------------------
// 2. Вырезаем диапазон строк R76–R145
// ------------------------------------------------------------

const lines = String(tableSegment.text ?? '').split('\n');

let currentRow = null;
let capturing = false;
const slicedLines = [];

for (const line of lines) {
  const rowMatch = line.match(/^Строка R(\d+):\s*$/);

  if (rowMatch) {
    currentRow = Number(rowMatch[1]);
    capturing =
      currentRow >= START_ROW &&
      currentRow <= END_ROW;
  }

  if (capturing) {
    slicedLines.push(line);
  }
}

const slicedTableText = slicedLines.join('\n').trim();

if (!slicedTableText) {
  throw new Error(
    `[TEST oversized table slice] В диапазоне R${START_ROW}–R${END_ROW} ничего не найдено`
  );
}

// ------------------------------------------------------------
// 3. Оставляем overlap + наш урезанный primary block
// ------------------------------------------------------------

const overlapSegments = source.ai_segments.filter(
  segment => segment.scope === 'overlap'
);

const slicedTableSegment = {
  ...tableSegment,
  text: slicedTableText,
};

source.ai_segments = [
  ...overlapSegments,
  slicedTableSegment,
];

// ------------------------------------------------------------
// 4. Корректируем analysis_unit_meta
// ------------------------------------------------------------

source.analysis_unit_meta = {
  ...source.analysis_unit_meta,

  part_index: 2,
  parts_total: 3,

  primary_semantic_block_ids: [
    oversizedTableId,
  ],

  overlap_semantic_block_ids:
    overlapSegments.map(
      segment => segment.semantic_block_id
    ),

  flags: {
    ...source.analysis_unit_meta.flags,
    oversized_atomic_block: false,
    contains_table: true,
    table_semantic_block_ids: [
      oversizedTableId,
    ],
  },

  test_slice: {
    enabled: true,
    start_row: START_ROW,
    end_row: END_ROW,
    original_analysis_unit_id:
      TARGET_ANALYSIS_UNIT_ID,
  },
};

// ------------------------------------------------------------
// 5. Сужаем provenance только до реально используемых blocks
// ------------------------------------------------------------

const allowedIds = new Set([
  oversizedTableId,
  ...overlapSegments.map(
    segment => segment.semantic_block_id
  ),
]);

const originalProvenanceIndex =
  source.provenance?.index ?? {};

const newProvenanceIndex = {};

for (const id of allowedIds) {
  if (originalProvenanceIndex[id]) {
    newProvenanceIndex[id] =
      originalProvenanceIndex[id];
  }
}

source.provenance = {
  ...source.provenance,
  index: newProvenanceIndex,

  total_semantic_blocks_count:
    source.ai_segments.length,

  primary_semantic_blocks_count: 1,

  overlap_semantic_blocks_count:
    overlapSegments.length,
};

// ------------------------------------------------------------
// 6. Пересобираем user_prompt
// ------------------------------------------------------------

const segmentPrompt = source.ai_segments
  .map(segment => {
    return [
      `[SEMANTIC_BLOCK id="${segment.semantic_block_id}" scope="${segment.scope}" type="${segment.type}" role="${segment.role}"]`,
      segment.text,
      '[/SEMANTIC_BLOCK]',
    ].join('\n');
  })
  .join('\n\n');

source.ai_request = {
  ...source.ai_request,

  user_prompt: [
    'Проанализируй только приведённую ниже часть тендерного документа.',
    '',
    'Найди все факты из каталога tender_fields_v1, которые явно подтверждаются содержимым SEMANTIC_BLOCK.',
    '',
    'Метаданные ниже предоставлены только для навигации и понимания контекста.',
    'Не используй их как evidence.',
    '',
    '',
    'КОНТЕКСТ',
    '',
    `analysis_unit_id: ${source.analysis_unit_meta.analysis_unit_id}`,
    `Файл документа: ${source.document?.file_name ?? ''}`,
    `Раздел: ${source.analysis_unit_meta.section_title ?? ''}`,
    `Часть раздела: TEST slice R${START_ROW}–R${END_ROW}`,
    '',
    '',
    'SEMANTIC BLOCKS',
    '',
    segmentPrompt,
    '',
    '',
    'Верни результат строго по схеме ai_extractor_v1.',
    '',
    'Если в этой analysis unit нет ни одного целевого факта, верни пустой массив facts.',
  ].join('\n'),
};

// ------------------------------------------------------------
// 7. Обновляем диагностическую статистику
// ------------------------------------------------------------

const systemChars =
  source.ai_request?.system_prompt?.length ?? 0;

const userChars =
  source.ai_request?.user_prompt?.length ?? 0;

const totalChars =
  systemChars + userChars;

source.ai_request.stats = {
  ...(source.ai_request.stats ?? {}),

  system_characters: systemChars,
  user_characters: userChars,
  total_characters: totalChars,

  // только грубая оценка для теста
  estimated_input_tokens:
    Math.ceil(totalChars / 3),

  semantic_blocks_count:
    source.ai_segments.length,

  primary_blocks_count: 1,

  overlap_blocks_count:
    overlapSegments.length,

  test_slice: {
    start_row: START_ROW,
    end_row: END_ROW,
  },
};

return [
  {
    json: source,
  },
];

const CONFIG = {
  validatorResponseVersion: 'ai_validator_response_check_v1',

  expectedSchemaVersion: 'ai_validator_v1',

  sourceNodeName: 'Проверить и привязать evidence ТЕСТОВАЯ',

  maxReasonNoteLength: 1000,
};


// ============================================================
// 1. РАЗРЕШЁННЫЕ ЗНАЧЕНИЯ
// ============================================================

const ALLOWED_VERDICTS = new Set([
  'confirmed',
  'requires_review',
  'rejected',
]);


const ALLOWED_REASON_CODES = new Set([
  'wrong_field_classification',
  'value_not_supported',
  'overinterpretation',
  'missing_qualification',
  'insufficient_evidence',
  'conflicting_evidence',
  'source_quality_issue',
  'template_or_placeholder',
  'other',
]);


const ROOT_ALLOWED_KEYS = new Set([
  'schema_version',
  'analysis_unit_id',
  'validations',
]);


const VALIDATION_ALLOWED_KEYS = new Set([
  'fact_index',
  'field_key',
  'verdict',
  'confidence',
  'reason_code',
  'reason_note',
]);


// ============================================================
// 2. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ============================================================

function fail(itemIndex, message) {
  throw new Error(
    `[Проверить ответ AI Validator] Item ${itemIndex + 1}: ${message}`
  );
}


function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}


function assertNoExtraKeys(
  object,
  allowedKeys,
  itemIndex,
  path
) {
  for (const key of Object.keys(object)) {
    if (!allowedKeys.has(key)) {
      fail(
        itemIndex,
        `${path}: обнаружено недопустимое поле "${key}".`
      );
    }
  }
}


function assertString(
  value,
  itemIndex,
  path,
  {
    minLength = 1,
    maxLength = Infinity,
  } = {}
) {
  if (typeof value !== 'string') {
    fail(
      itemIndex,
      `${path}: ожидалась строка.`
    );
  }

  if (value.length < minLength) {
    fail(
      itemIndex,
      `${path}: строка слишком короткая.`
    );
  }

  if (value.length > maxLength) {
    fail(
      itemIndex,
      `${path}: превышена максимальная длина ${maxLength}.`
    );
  }
}


function parseValidatorContent(
  content,
  itemIndex
) {
  if (
    typeof content !== 'string' ||
    content.trim().length === 0
  ) {
    fail(
      itemIndex,
      'choices[0].message.content пуст.'
    );
  }

  try {
    return JSON.parse(
      content.trim()
    );
  } catch (error) {
    fail(
      itemIndex,
      `Ответ AI Validator не является валидным JSON: ${error.message}`
    );
  }
}


// ============================================================
// 3. INPUT
// ============================================================

const validatorItems =
  $input.all();

const sourceItems =
  $(CONFIG.sourceNodeName).all();


if (validatorItems.length === 0) {
  throw new Error(
    '[Проверить ответ AI Validator] Нет входных items.'
  );
}


if (
  validatorItems.length !==
  sourceItems.length
) {
  throw new Error(
    `[Проверить ответ AI Validator] Количество items не совпадает: ` +
    `AI Validator=${validatorItems.length}, ` +
    `${CONFIG.sourceNodeName}=${sourceItems.length}.`
  );
}


// ============================================================
// 4. ОБРАБОТКА КАЖДОГО ITEM
// ============================================================

return validatorItems.map(
  (
    validatorItem,
    itemIndex
  ) => {
    const apiResponse =
      validatorItem?.json;

    const source =
      sourceItems[itemIndex]?.json;


    // --------------------------------------------------------
    // Проверяем входные данные
    // --------------------------------------------------------

    if (!isObject(apiResponse)) {
      fail(
        itemIndex,
        'Некорректный ответ HTTP Request AI Validator.'
      );
    }


    if (!isObject(source)) {
      fail(
        itemIndex,
        `Не удалось получить данные из ноды "${CONFIG.sourceNodeName}".`
      );
    }


    if (
      source.evidence_validation?.passed !== true
    ) {
      fail(
        itemIndex,
        'Входные facts не прошли предыдущую evidence validation.'
      );
    }


    if (
      !Array.isArray(
        source.verified_facts
      )
    ) {
      fail(
        itemIndex,
        'verified_facts отсутствует.'
      );
    }


    // --------------------------------------------------------
    // Проверяем HTTP-ответ AI Validator
    // --------------------------------------------------------

    if (
      !Array.isArray(
        apiResponse.choices
      ) ||
      apiResponse.choices.length === 0
    ) {
      fail(
        itemIndex,
        'AI Validator не вернул choices.'
      );
    }


    const choice =
      apiResponse.choices[0];


    if (!isObject(choice)) {
      fail(
        itemIndex,
        'choices[0] имеет неверный формат.'
      );
    }


    if (
      choice.finish_reason !== 'stop'
    ) {
      fail(
        itemIndex,
        `AI Validator завершил ответ с finish_reason="${choice.finish_reason}".`
      );
    }


    if (!isObject(choice.message)) {
      fail(
        itemIndex,
        'choices[0].message отсутствует.'
      );
    }


    // --------------------------------------------------------
    // Парсим JSON второго AI
    // --------------------------------------------------------

    const parsed =
      parseValidatorContent(
        choice.message.content,
        itemIndex
      );


    if (!isObject(parsed)) {
      fail(
        itemIndex,
        'Корневой JSON AI Validator должен быть объектом.'
      );
    }


    // ========================================================
    // 5. ROOT VALIDATION
    // ========================================================

    assertNoExtraKeys(
      parsed,
      ROOT_ALLOWED_KEYS,
      itemIndex,
      'AIValidatorV1'
    );


    if (
      parsed.schema_version !==
      CONFIG.expectedSchemaVersion
    ) {
      fail(
        itemIndex,
        `Неверный schema_version: "${parsed.schema_version}".`
      );
    }


    const expectedAnalysisUnitId =
      source.analysis_unit_meta
        ?.analysis_unit_id;


    assertString(
      expectedAnalysisUnitId,
      itemIndex,
      'analysis_unit_meta.analysis_unit_id'
    );


    if (
      parsed.analysis_unit_id !==
      expectedAnalysisUnitId
    ) {
      fail(
        itemIndex,
        `analysis_unit_id не совпадает. ` +
        `Ожидался "${expectedAnalysisUnitId}", ` +
        `получен "${parsed.analysis_unit_id}".`
      );
    }


    if (
      !Array.isArray(
        parsed.validations
      )
    ) {
      fail(
        itemIndex,
        'validations должен быть массивом.'
      );
    }


    // ========================================================
    // 6. ПРОВЕРЯЕМ SOURCE FACTS
    // ========================================================

    const sourceFacts =
      source.verified_facts;


    const sourceFactMap =
      new Map();


    for (
      let sourceIndex = 0;
      sourceIndex < sourceFacts.length;
      sourceIndex++
    ) {
      const fact =
        sourceFacts[sourceIndex];


      if (!isObject(fact)) {
        fail(
          itemIndex,
          `verified_facts[${sourceIndex}] имеет неверный формат.`
        );
      }


      if (
        !Number.isInteger(
          fact.fact_index
        )
      ) {
        fail(
          itemIndex,
          `verified_facts[${sourceIndex}].fact_index должен быть целым числом.`
        );
      }


      if (
        sourceFactMap.has(
          fact.fact_index
        )
      ) {
        fail(
          itemIndex,
          `В verified_facts повторяется fact_index=${fact.fact_index}.`
        );
      }


      assertString(
        fact.field_key,
        itemIndex,
        `verified_facts[${sourceIndex}].field_key`
      );


      sourceFactMap.set(
        fact.fact_index,
        fact
      );
    }


    // --------------------------------------------------------
    // Количество validations обязано совпадать
    // --------------------------------------------------------

    if (
      parsed.validations.length !==
      sourceFacts.length
    ) {
      fail(
        itemIndex,
        `AI Validator должен вернуть ровно одну validation на каждый fact. ` +
        `Ожидалось ${sourceFacts.length}, ` +
        `получено ${parsed.validations.length}.`
      );
    }


    // ========================================================
    // 7. ПРОВЕРЯЕМ КАЖДУЮ VALIDATION
    // ========================================================

    const validationMap =
      new Map();


    parsed.validations.forEach(
      (
        validation,
        validationIndex
      ) => {
        const path =
          `validations[${validationIndex}]`;


        if (!isObject(validation)) {
          fail(
            itemIndex,
            `${path}: validation должен быть объектом.`
          );
        }


        assertNoExtraKeys(
          validation,
          VALIDATION_ALLOWED_KEYS,
          itemIndex,
          path
        );


        // ----------------------------------------------------
        // fact_index
        // ----------------------------------------------------

        if (
          !Number.isInteger(
            validation.fact_index
          )
        ) {
          fail(
            itemIndex,
            `${path}.fact_index должен быть целым числом.`
          );
        }


        if (
          validationMap.has(
            validation.fact_index
          )
        ) {
          fail(
            itemIndex,
            `${path}: fact_index=${validation.fact_index} повторяется.`
          );
        }


        const originalFact =
          sourceFactMap.get(
            validation.fact_index
          );


        if (!originalFact) {
          fail(
            itemIndex,
            `${path}: AI Validator добавил неизвестный fact_index=${validation.fact_index}.`
          );
        }


        // ----------------------------------------------------
        // field_key
        // ----------------------------------------------------

        assertString(
          validation.field_key,
          itemIndex,
          `${path}.field_key`
        );


        if (
          validation.field_key !==
          originalFact.field_key
        ) {
          fail(
            itemIndex,
            `${path}: AI Validator изменил field_key. ` +
            `Для fact_index=${validation.fact_index} ` +
            `ожидался "${originalFact.field_key}", ` +
            `получен "${validation.field_key}".`
          );
        }


        // ----------------------------------------------------
        // verdict
        // ----------------------------------------------------

        if (
          !ALLOWED_VERDICTS.has(
            validation.verdict
          )
        ) {
          fail(
            itemIndex,
            `${path}: недопустимый verdict "${validation.verdict}".`
          );
        }


        // ----------------------------------------------------
        // confidence
        // ----------------------------------------------------

        if (
          typeof validation.confidence !== 'number' ||
          !Number.isFinite(
            validation.confidence
          ) ||
          validation.confidence < 0 ||
          validation.confidence > 1
        ) {
          fail(
            itemIndex,
            `${path}.confidence должен быть числом от 0 до 1.`
          );
        }


        // ----------------------------------------------------
        // reason_code / reason_note
        // ----------------------------------------------------

        if (
          validation.verdict ===
          'confirmed'
        ) {
          if (
            validation.reason_code !== null
          ) {
            fail(
              itemIndex,
              `${path}: для verdict=confirmed reason_code должен быть null.`
            );
          }


          if (
            validation.reason_note !== null
          ) {
            fail(
              itemIndex,
              `${path}: для verdict=confirmed reason_note должен быть null.`
            );
          }
        }


        if (
          validation.verdict ===
            'requires_review' ||
          validation.verdict ===
            'rejected'
        ) {
          if (
            !ALLOWED_REASON_CODES.has(
              validation.reason_code
            )
          ) {
            fail(
              itemIndex,
              `${path}: для verdict=${validation.verdict} ` +
              `нужен допустимый reason_code. Получено "${validation.reason_code}".`
            );
          }


          if (
            validation.reason_note !== null
          ) {
            assertString(
              validation.reason_note,
              itemIndex,
              `${path}.reason_note`,
              {
                minLength: 1,
                maxLength:
                  CONFIG.maxReasonNoteLength,
              }
            );
          }
        }


        validationMap.set(
          validation.fact_index,
          validation
        );
      }
    );


    // ========================================================
    // 8. ПРОВЕРЯЕМ, ЧТО НЕ ПРОПУЩЕН НИ ОДИН FACT
    // ========================================================

    for (
      const fact
      of sourceFacts
    ) {
      if (
        !validationMap.has(
          fact.fact_index
        )
      ) {
        fail(
          itemIndex,
          `AI Validator пропустил fact_index=${fact.fact_index}.`
        );
      }
    }


    // ========================================================
    // 9. ОБЪЕДИНЯЕМ EXTRACTOR + VALIDATOR
    // ========================================================

    const validatedFacts =
      sourceFacts.map(
        fact => {
          const validation =
            validationMap.get(
              fact.fact_index
            );


          return {
            fact_index:
              fact.fact_index,

            field_key:
              fact.field_key,

            value_text:
              fact.value_text,


            // --------------------------------------------
            // Первый AI
            // --------------------------------------------

            extractor: {
              status:
                fact.status,

              confidence:
                fact.confidence,

              review_reason_code:
                fact.review_reason_code,

              review_note:
                fact.review_note,
            },


            // --------------------------------------------
            // Второй AI
            // --------------------------------------------

            ai_validation: {
              verdict:
                validation.verdict,

              confidence:
                validation.confidence,

              reason_code:
                validation.reason_code,

              reason_note:
                validation.reason_note,
            },


            // --------------------------------------------
            // Решение для следующего этапа
            // --------------------------------------------

            processing_status:
              validation.verdict,

            accepted_for_normalization:
              validation.verdict ===
              'confirmed',


            // --------------------------------------------
            // Настоящий evidence + provenance
            // --------------------------------------------

            evidence:
              fact.evidence,
          };
        }
      );


    // ========================================================
    // 10. СТАТИСТИКА
    // ========================================================

    const confirmedCount =
      validatedFacts.filter(
        fact =>
          fact.ai_validation
            .verdict ===
          'confirmed'
      ).length;


    const requiresReviewCount =
      validatedFacts.filter(
        fact =>
          fact.ai_validation
            .verdict ===
          'requires_review'
      ).length;


    const rejectedCount =
      validatedFacts.filter(
        fact =>
          fact.ai_validation
            .verdict ===
          'rejected'
      ).length;


    const usage =
      isObject(
        apiResponse.usage
      )
        ? apiResponse.usage
        : {};


    const reasoningTokens =
      usage
        ?.completion_tokens_details
        ?.reasoning_tokens ??
      null;


    // ========================================================
    // 11. OUTPUT
    // ========================================================

    return {
      json: {
        tender:
          source.tender ??
          null,

        document:
          source.document ??
          null,

        analysis_batch:
          source.analysis_batch ??
          null,

        analysis_unit_meta:
          source.analysis_unit_meta ??
          null,


        // --------------------------------------------
        // Первый AI + его evidence validation
        // --------------------------------------------

        extractor:
          source.extractor ??
          null,

        evidence_validation:
          source.evidence_validation ??
          null,


        // --------------------------------------------
        // Второй AI
        // --------------------------------------------

        ai_validator: {
          provider:
            'deepseek',

          response_id:
            apiResponse.id ??
            null,

          model:
            apiResponse.model ??
            null,

          finish_reason:
            choice.finish_reason,

          system_fingerprint:
            apiResponse.system_fingerprint ??
            null,

          schema_version:
            parsed.schema_version,

          usage: {
            prompt_tokens:
              usage.prompt_tokens ??
              null,

            completion_tokens:
              usage.completion_tokens ??
              null,

            reasoning_tokens:
              reasoningTokens,

            total_tokens:
              usage.total_tokens ??
              null,

            prompt_cache_hit_tokens:
              usage.prompt_cache_hit_tokens ??
              null,

            prompt_cache_miss_tokens:
              usage.prompt_cache_miss_tokens ??
              null,
          },
        },


        // --------------------------------------------
        // Проверка ответа второго AI
        // --------------------------------------------

        ai_validator_response_check: {
          version:
            CONFIG.validatorResponseVersion,

          passed:
            true,

          expected_facts_count:
            sourceFacts.length,

          received_validations_count:
            parsed.validations.length,

          confirmed_count:
            confirmedCount,

          requires_review_count:
            requiresReviewCount,

          rejected_count:
            rejectedCount,

          schema_valid:
            true,

          analysis_unit_id_valid:
